from fastapi import HTTPException, UploadFile

@app.post("/upload")
async def upload(file: UploadFile):
    data = await file.read()  # bytes
    if len(data) > 1_000_000:
        raise HTTPException(status_code=413, detail="File too large")
    return {"filename": file.filename,
            "content_type": file.content_type,
            "size": len(data)}

from fastapi import File, Form

@app.post("/many")
async def many(files: list[UploadFile]):
    return {"names": [f.filename for f in files]}

@app.post("/profile")
async def profile(name: str = Form(), avatar: UploadFile = File()):
    return {"name": name, "avatar": avatar.filename}

from fastapi import BackgroundTasks

def send_welcome(email: str):
    print(f"Welcome email to {email}")  # slow work

@app.post("/signup", status_code=201)
def signup(email: str, background_tasks: BackgroundTasks):
    background_tasks.add_task(send_welcome, email)
    return {"message": "Account created"}

